class StringStream {
    constructor(source) {
        this.b = source;
        this.c = 0;
    }
    eos() {
        return this.c >= this.b.length;
    }
    next() {
        const next = this.peek();
        this.advance();
        return next;
    }
    peek() {
        return this.b[this.c];
    }
    advance() {
        this.c++;
    }
}
